 await test('internal taxonomy metadata is hidden from mapping choices and warnings', async()=>{
  const current=categoryDesign();
  const keys=['_nova_weglot_i18n_de','_nova_weglot_languages','_nova_localized_term_example','nova_batch_translation_snapshots','nova_batch_product_ids','nova_batch_meta_exists','fixture_translation_snapshots','yoast_head','yoast_head_json','barcode'];
  const internal=keys.map((key,index)=>({target:'/term_fields/unavailable/'+index,label:key,custom_field_key:key,writable:false,declaration_required:true}));
  current.fields[1].kind='top_content';
  current.fields.push(...internal);
  current.excluded_fields=keys.map(key=>({key,label:key,declaration_required:true,suggested_schema:{type:'string'}}));
  current.fields.push({target:'/term_fields/values/seo',label:'SEO title',custom_field_key:'wpseo_title',writable:true});
  current.excluded_fields.push({key:'editorial_summary',label:'Editorial summary',declaration_required:true,suggested_schema:{type:'string'}});
  const captured=ui.designResult(current,'core');
  assert(!captured.fields.some(field=>keys.includes(field.custom_field_key)));
  assert.deepEqual(captured.excluded_fields.map(field=>field.key),['editorial_summary']);
  assert(captured.fields.some(field=>field.custom_field_key==='wpseo_title'));
  assert.deepEqual(captured.blueprint,current.blueprint);
  assert.deepEqual(captured.recipe_preset,current.recipe_preset);
  assert.equal(current.fields.length,14,'Normalizing the editor must not mutate the captured response');
  const t=await categoryMounted({request:async(path)=>path==='/design'?clone(current):undefined});
  t.controller.next();await t.controller.capture(18);t.controller.next();
  assert(keys.every(key=>!t.host.textContent.includes(key)),'Internal metadata appeared in the mounted editor');
  nativeControl(t.host,'Top category content').events.click();
  assert(t.host.textContent.includes('Preserve destination content'));
  assert(t.host.textContent.includes('New categories and tags leave this field empty.'));
  assert.equal(t.controller.state.recipe.bindings.length,0);
 });
